package sample

import (
	"os"
	"strings"
	"sync"
)

// Cache holds names loaded from disk.
type Cache struct {
	mu    sync.Mutex
	names map[string]int
}

func LoadNames(path string) ([]string, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	buf := make([]byte, 4096)
	n, _ := f.Read(buf)
	return strings.Split(string(buf[:n]), "\n"), nil
}

func (c *Cache) Add(name string) {
	c.names[name]++
}

func (c *Cache) Count(name string) int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.names[name]
}
